/** Sorted list of champion aliases */
export const CHAMPION_LIST: string[] = Object.keys(CHAMPION_CATALOG)

/** Get the base (default) skin ID for a champion */
export function getBaseSkinId(alias: string): string | undefined {
  const entry = CHAMPION_CATALOG[alias]
  if (!entry) return undefined
  const base = entry.skins.find((s) => s.isBase)
  return base?.id ?? entry.skins[0]?.id
}
